SELECT n.gender, rt.role, cn.name, COUNT(*)
FROM title as t, movie_companies as mc, company_name as cn, company_type as ct, kind_type as kt, cast_info as ci, name as n, role_type as rt, movie_info as mi1, info_type as it1, person_info as pi, info_type as it2, non_leaf_1357
WHERE (kt.kind IN ('episode','movie','tv mini series','tv movie','tv series','video game')) AND (t.production_year >= 1945) AND mc.movie_id = non_leaf_1357.ci_movie_id AND (pi.info ILIKE '%20%') AND ct.id = mc.company_type_id AND (it1.id IN ('8')) AND cn.id = mc.company_id AND it2.id = non_leaf_1357.pi_info_type_id AND (it2.id IN ('23')) AND (mi1.info ILIKE '%ca%') AND (t.production_year <= 1990) AND mc.movie_id = non_leaf_1357.t_id AND (rt.role IN ('actor','cinematographer','costume designer','editor','guest','miscellaneous crew','producer','production designer','writer'));